import 'reflect-metadata';

import fastifyCompress from '@fastify/compress';
import fastifyCors from '@fastify/cors';
import fastifyHelmet from '@fastify/helmet';
import fastifyRateLimit from '@fastify/rate-limit';
import { VersioningType } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { FastifyAdapter, type NestFastifyApplication } from '@nestjs/platform-fastify';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { Logger, PinoLogger } from 'nestjs-pino';

import { AppModule } from './app.module';
import { AppConfigService } from './common/config/configuration';
import { startSelfPing } from './common/keep-alive/self-ping';

async function bootstrap(): Promise<void> {
  const app = await NestFactory.create<NestFastifyApplication>(AppModule, new FastifyAdapter({ trustProxy: true }), {
    bufferLogs: true,
  });

  const config = app.get(AppConfigService);
  app.useLogger(app.get(Logger));

  const fastify = app.getHttpAdapter().getInstance();
  await fastify.register(fastifyHelmet, { global: true });
  await fastify.register(fastifyCompress);
  await fastify.register(fastifyCors, {
    origin: (origin, cb) => {
      // Mobile native apps (React Native, Flutter, Swift/Kotlin), curl, server-to-server have no Origin header
      if (!origin) {
        cb(null, true);
        return;
      }
      // Check configured origins
      if (
        config.corsOrigins.includes('*') ||
        config.corsOrigins.includes(origin) ||
        // Allow localhost and local IP origins for local web/mobile development
        /^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?$/.test(origin) ||
        // Allow hybrid mobile schemes
        origin.startsWith('capacitor://') ||
        origin.startsWith('ionic://')
      ) {
        cb(null, true);
        return;
      }
      cb(new Error('Not allowed by CORS'), false);
    },
    credentials: true,
    methods: ['GET', 'POST', 'PUT', 'PATCH', 'DELETE', 'OPTIONS', 'HEAD'],
    allowedHeaders: [
      'Content-Type',
      'Authorization',
      'Idempotency-Key',
      'x-correlation-id',
      'x-region',
      'Accept',
      'Origin',
      'X-Requested-With',
    ],
    exposedHeaders: ['x-correlation-id', 'content-disposition'],
  });
  await fastify.register(fastifyRateLimit, { max: 100, timeWindow: '1 minute' });

  // Echoes the correlation id (see app.module.ts's pinoHttp.genReqId) back to the caller.
  fastify.addHook('onSend', (request, reply, payload, done) => {
    reply.header('x-correlation-id', request.id);
    done(null, payload);
  });

  app.setGlobalPrefix('api');
  app.enableVersioning({ type: VersioningType.URI, defaultVersion: '1' });
  app.enableShutdownHooks();

  // Served in every environment (including production) so the frontend teams consuming this API
  // — the LifeCome Live web app and mobile app — have one live reference for request/response
  // shapes, rather than a doc that only exists locally.
  const document = SwaggerModule.createDocument(
    app,
    new DocumentBuilder()
      .setTitle('LifeCome Live API')
      .setDescription('Modular-monolith API for the LifeCome Live platform (Web and Mobile apps). See ../docs/prd for the product blueprint.')
      .setVersion('0.1.0')
      .addBearerAuth(
        {
          type: 'http',
          scheme: 'bearer',
          bearerFormat: 'JWT',
          description: 'Patient session JWT (obtained from /api/v1/identity/login or /api/v1/identity/otp/verify)',
        },
        'patient-jwt',
      )
      .addBearerAuth(
        {
          type: 'http',
          scheme: 'bearer',
          bearerFormat: 'JWT',
          description: 'Staff JWT for admin operations console (/api/v1/auth/login)',
        },
        'staff-jwt',
      )
      .build(),
  );
  SwaggerModule.setup('docs', app, document, { useGlobalPrefix: true });

  await app.listen(config.port, '0.0.0.0');

  // PinoLogger is request-scoped, so it can't be fetched with `get()` outside a request — only
  // `resolve()` (which creates its own DI sub-context) works here, at the top level of bootstrap.
  const pinoLogger = await app.resolve(PinoLogger);
  pinoLogger.setContext('SelfPing');
  startSelfPing(pinoLogger);
}

bootstrap().catch((error: unknown) => {
  console.error('Failed to start:', error);
  process.exit(1);
});
